function main({video,body}) {
  video=video??body?.video;
  if(typeof video!=='string')throw Error('Provide a YouTube URL');
  const v=video.trim();let id;
  if(/^[A-Za-z0-9_-]{11}$/.test(v))id=v;
  else {let m=v.match(/^https?:\/\/(?:www\.|m\.)?youtube\.com\/watch\?([^#]*)/i);if(m)id=m[1].split('&').find(x=>x.startsWith('v='))?.slice(2);else id=v.match(/^https?:\/\/(?:www\.|m\.)?youtube\.com\/(?:shorts|embed|live)\/([A-Za-z0-9_-]{11})(?:[?#/]|$)/i)?.[1]??v.match(/^https?:\/\/(?:www\.)?youtu\.be\/([A-Za-z0-9_-]{11})(?:[?#/]|$)/i)?.[1];}
  if(!/^[A-Za-z0-9_-]{11}$/.test(id??''))throw Error('Provide a supported YouTube video URL or ID');
  return {videoId:id};
}

