function main({requestedId,videoId,transcript}) {
  if(videoId!==requestedId)throw Error('Transcript belongs to another video');
  if(typeof transcript!=='string'||!transcript.trim())throw Error('No transcript available');
  return {videoId,transcript:transcript.replace(/\s+/g,' ').replace(/\s([.,!?])/g,'$1').trim()};
}

